slides.custom_css:
.sn-page{
  position:absolute;
  left:73px;
  top:232px;
  width:1774px;
  height:776px;
  color:#fff;
  font-family:var(--fs-font-cjk);
}
.sn-page *{ box-sizing:border-box; letter-spacing:0; }
.brand-row{
  position:absolute;
  left:0;
  top:0;
  width:1774px;
  height:54px;
  display:flex;
  align-items:center;
  gap:18px;
  color:#fff;
  font-size:16px;
  line-height:1.1;
}
.brand-row img{
  width:116px;
  height:42px;
  object-fit:contain;
  padding:6px 10px;
  border-radius:8px;
  background:rgba(255,255,255,.92);
}
.hero-result{
  position:absolute;
  left:0;
  top:72px;
  width:565px;
  height:704px;
  padding:30px 28px 28px;
  display:flex;
  flex-direction:column;
  border:1px solid rgba(255,255,255,.15);
  border-radius:8px;
  background:linear-gradient(145deg, rgba(60,127,255,.18), rgba(24,214,163,.08));
}
.kicker{
  margin:0 0 16px;
  color:#6ee7c7;
  font-size:24px;
  line-height:1.15;
  font-weight:600;
}
.hero-result h3{
  margin:0;
  max-width:500px;
  color:#fff;
  font-size:48px;
  line-height:1.08;
  font-weight:600;
}
.hero-result h3 span{
  display:block;
}
.metric-grid{
  display:grid;
  grid-template-columns:1fr;
  gap:12px;
  margin-top:20px;
}
.metric-card{
  min-height:118px;
  padding:16px 22px;
  display:flex;
  flex-direction:column;
  justify-content:center;
  border:1px solid rgba(255,255,255,.16);
  border-radius:8px;
  background:rgba(255,255,255,.08);
}
.metric-card.primary{
  background:linear-gradient(135deg, rgba(246,195,91,.28), rgba(60,127,255,.14));
}
.metric-num{
  display:block;
  color:#fff;
  font-size:72px; /* allow:typescale */
  line-height:.95;
  font-weight:800;
}
.metric-label{
  display:block;
  margin-top:8px;
  color:#fff;
  font-size:24px;
  line-height:1.12;
  font-weight:500;
}
.context-strip{
  margin-top:16px;
  display:grid;
  grid-template-columns:repeat(3, 1fr);
  gap:8px;
}
.context-strip span{
  min-height:44px;
  padding:0 8px;
  display:flex;
  align-items:center;
  justify-content:center;
  text-align:center;
  color:#fff;
  font-size:24px;
  line-height:1.1;
  font-weight:500;
  white-space:nowrap;
  border:1px solid rgba(110,231,199,.28);
  border-radius:8px;
  background:rgba(11,22,44,.45);
}
.mechanism{
  position:absolute;
  left:600px;
  top:72px;
  width:640px;
  height:704px;
}
.section-title span{
  display:block;
  color:#6ee7c7;
  font-size:16px;
  line-height:1.1;
  font-weight:700;
}
.section-title strong{
  display:block;
  margin-top:8px;
  color:#fff;
  font-size:28px;
  line-height:1.18;
  font-weight:600;
}
.pipeline-board{
  position:relative;
  margin-top:22px;
  height:430px;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.16);
  border-radius:8px;
  background:
    linear-gradient(135deg, rgba(20,86,240,.16), rgba(20,199,165,.08) 44%, rgba(246,195,91,.08)),
    rgba(255,255,255,.05);
}
.pipeline-board::before{
  content:"";
  position:absolute;
  inset:18px;
  border:1px solid rgba(110,231,199,.12);
  border-radius:8px;
  pointer-events:none;
}
.pipeline-beam{
  position:absolute;
  left:56px;
  right:56px;
  top:144px;
  height:4px;
  border-radius:999px;
  background:rgba(255,255,255,.13);
}
.pipeline-beam i{
  display:block;
  width:100%;
  height:100%;
  border-radius:999px;
  background:linear-gradient(90deg,#1456f0 0%,#14c7a5 52%,#f6c35b 100%);
  box-shadow:0 0 24px rgba(20,199,165,.42);
}
.pipeline-row{
  position:absolute;
  left:24px;
  right:24px;
  top:54px;
  height:212px;
  display:grid;
  grid-template-columns:100px 12px 100px 12px 100px 12px 100px 12px 100px;
  gap:5px;
  align-items:center;
}
.pipe-card{
  position:relative;
  height:192px;
  padding:12px 10px 12px;
  overflow:hidden;
  border:1px solid rgba(255,255,255,.16);
  border-radius:8px;
  background:rgba(6,15,34,.72);
}
.pipe-card::after{
  content:"";
  position:absolute;
  left:0;
  right:0;
  top:0;
  height:3px;
  background:#1456f0;
}
.step-ai::after{ background:#14c7a5; }
.step-owner::after{ background:#f6c35b; }
.step-task::after{ background:#ff6b8a; }
.step-review::after{ background:#7c5cff; }
.pipe-index{
  display:block;
  color:#6ee7c7;
  font-size:24px;
  line-height:1;
  font-weight:700;
}
.pipe-glyph{
  width:52px;
  height:52px;
  display:flex;
  align-items:center;
  justify-content:center;
  margin:12px auto 10px;
  color:#fff;
  font-size:28px;
  line-height:1;
  font-weight:800;
  border:1px solid rgba(110,231,199,.36);
  border-radius:50%;
  background:linear-gradient(135deg, rgba(20,86,240,.52), rgba(20,199,165,.28));
  box-shadow:inset 0 0 18px rgba(255,255,255,.08);
}
.pipe-card b{
  min-height:58px;
  display:flex;
  align-items:center;
  justify-content:center;
  color:#fff;
  text-align:center;
  font-size:24px;
  line-height:1.12;
  font-weight:700;
  white-space:nowrap;
  text-wrap:balance;
}
.pipe-arrow{
  width:12px;
  height:12px;
  display:block;
  border-top:3px solid rgba(110,231,199,.82);
  border-right:3px solid rgba(110,231,199,.82);
  transform:rotate(45deg);
  filter:drop-shadow(0 0 10px rgba(110,231,199,.42));
}
.pipeline-caption{
  position:absolute;
  left:22px;
  right:22px;
  bottom:22px;
  min-height:108px;
  padding:18px 20px;
  border:1px solid rgba(246,195,91,.22);
  border-radius:8px;
  background:linear-gradient(135deg, rgba(246,195,91,.15), rgba(20,86,240,.10));
}
.pipeline-caption strong{
  display:block;
  color:#f6c35b;
  font-size:28px;
  line-height:1.1;
  font-weight:700;
}
.pipeline-caption p{
  margin:12px 0 0;
  color:#fff;
  font-size:24px;
  line-height:1.24;
  font-weight:400;
}
.pipeline-outcomes{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:12px;
  margin-top:16px;
}
.pipeline-outcomes div{
  min-height:118px;
  padding:18px 14px;
  border:1px solid rgba(255,255,255,.14);
  border-radius:8px;
  background:rgba(255,255,255,.07);
}
.pipeline-outcomes b{
  display:block;
  color:#fff;
  font-size:28px;
  line-height:1.1;
  font-weight:700;
}
.pipeline-outcomes span{
  display:block;
  margin-top:12px;
  color:#fff;
  font-size:24px;
  line-height:1.18;
  font-weight:400;
  white-space:nowrap;
}
.evidence{
  position:absolute;
  right:0;
  top:72px;
  width:495px;
  height:704px;
}
.feishu-demo{
  position:absolute;
  left:0;
  right:0;
  bottom:0;
  height:612px;
  overflow:hidden;
  display:flex;
  flex-direction:column;
  color:#1f2329;
  border:1px solid rgba(255,255,255,.28);
  border-radius:8px;
  background:#f7f8fa;
  box-shadow:0 24px 70px rgba(0,0,0,.28);
}
.demo-header{
  height:58px;
  flex:0 0 58px;
  display:flex;
  align-items:center;
  gap:12px;
  padding:12px 16px;
  background:#fff;
  border-bottom:1px solid #e5e6eb;
}
.group-badge{
  width:38px;
  height:38px;
  display:flex;
  align-items:center;
  justify-content:center;
  color:#12b886;
  font-size:16px;
  line-height:1.05;
  font-weight:700;
  text-align:center;
  border:1px solid #12b886;
  border-radius:50%;
  background:#effff8;
}
.group-name{
  min-width:0;
  flex:1;
}
.group-name strong{
  display:block;
  color:#1f2329;
  font-size:20px;
  line-height:1.1;
  font-weight:700;
  white-space:nowrap;
}
.group-name span{
  display:block;
  margin-top:5px;
  color:#646a73;
  font-size:16px;
  line-height:1.1;
}
.header-tools{
  display:flex;
  gap:8px;
}
.header-tools span{
  width:8px;
  height:8px;
  border-radius:50%;
  background:#a8abb2;
}
.demo-tabs{
  height:34px;
  flex:0 0 34px;
  display:flex;
  align-items:center;
  gap:8px;
  padding:0 14px;
  color:#4e5969;
  font-size:16px;
  line-height:1;
  background:#fff;
  border-bottom:1px solid #e5e6eb;
}
.demo-tabs span{
  height:24px;
  display:flex;
  align-items:center;
  padding:0 10px;
  border-radius:8px;
}
.demo-tabs .active{
  color:#1456f0;
  font-weight:700;
  background:#e8f0ff;
}
.chat-scroll{
  flex:1;
  min-height:0;
  padding:12px;
  overflow-x:hidden;
  overflow-y:auto;
  background:linear-gradient(180deg,#fbfcff 0%,#f0f2f5 100%);
}
.user-question{
  display:flex;
  gap:10px;
  align-items:flex-start;
}
.avatar{
  width:34px;
  height:34px;
  flex:0 0 34px;
  display:flex;
  align-items:center;
  justify-content:center;
  color:#fff;
  font-size:16px;
  line-height:1;
  font-weight:700;
  border-radius:50%;
}
.avatar.user{ background:#5b65f5; }
.avatar.bot{ background:linear-gradient(135deg,#1456f0,#14c7a5); }
.question-card{
  max-width:365px;
  padding:10px 12px;
  color:#1f2329;
  font-size:16px;
  line-height:1.32;
  border-radius:8px;
  background:#fff;
  box-shadow:0 1px 4px rgba(31,35,41,.08);
}
.question-card b{ color:#1456f0; font-weight:700; }
.ask-panel{
  position:relative;
  margin-top:10px;
}
.ask-toggle{
  position:absolute;
  opacity:0;
  pointer-events:none;
}
.prompt-row{
  height:46px;
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:7px;
  margin:0 0 8px 44px;
}
.prompt-row label{
  height:38px;
  display:flex;
  align-items:center;
  justify-content:center;
  color:#4e5969;
  font-size:16px;
  line-height:1;
  font-weight:700;
  border:1px solid #dee3ff;
  border-radius:8px;
  background:#fff;
  cursor:pointer;
}
#ask-progress:checked ~ .prompt-row label[for="ask-progress"],
#ask-risk:checked ~ .prompt-row label[for="ask-risk"],
#ask-action:checked ~ .prompt-row label[for="ask-action"]{
  color:#1456f0;
  border-color:#8da8ff;
  background:#edf3ff;
}
.bot-row{
  display:flex;
  gap:10px;
  align-items:flex-start;
}
.bot-card{
  position:relative;
  flex:1;
  min-width:0;
  padding:10px;
  border:1px solid #e5e6eb;
  border-radius:8px;
  background:#fff;
  box-shadow:0 10px 28px rgba(31,35,41,.10);
}
.bot-meta{
  display:flex;
  align-items:center;
  gap:8px;
  color:#646a73;
  font-size:16px;
  line-height:1;
}
.bot-meta strong{
  color:#1f2329;
  font-size:16px;
  line-height:1;
  font-weight:700;
}
.typing-line{
  position:absolute;
  right:12px;
  top:15px;
  height:12px;
  display:flex;
  align-items:center;
  gap:4px;
  margin-top:0;
}
.typing-line span{
  width:5px;
  height:5px;
  border-radius:50%;
  background:#8da8ff;
}
.answer-state{ display:none; }
#ask-progress:checked ~ .bot-row .state-progress,
#ask-risk:checked ~ .bot-row .state-risk,
#ask-action:checked ~ .bot-row .state-action{
  display:block;
}
.answer-title{
  display:flex;
  align-items:flex-end;
  justify-content:space-between;
  gap:8px;
  margin-top:8px;
  padding-bottom:8px;
  border-bottom:1px solid #eff0f2;
}
.answer-title b{
  color:#1f2329;
  font-size:20px;
  line-height:1.1;
  font-weight:800;
}
.answer-title span{
  color:#646a73;
  font-size:16px;
  line-height:1.15;
  text-align:right;
}
.lag-list{
  display:grid;
  gap:6px;
  margin-top:8px;
}
.lag-row{
  --w:0%;
  position:relative;
  min-height:32px;
  overflow:hidden;
  display:grid;
  grid-template-columns:72px 1fr;
  align-items:center;
  gap:8px;
  padding:5px 8px;
  border-radius:8px;
  background:#f5f7fa;
}
.lag-row i{
  position:absolute;
  left:0;
  bottom:0;
  height:3px;
  width:var(--w);
  background:#1456f0;
}
.lag-row.danger i{ background:#f54a45; }
.lag-row.warn i{ background:#f5a623; }
.lag-row.ok i{ background:#25b864; }
.lag-row b{
  color:#1f2329;
  font-size:16px;
  line-height:1.1;
  font-weight:800;
}
.lag-row span{
  color:#1f2329;
  font-size:16px;
  line-height:1.15;
  font-weight:700;
}
.ai-note{
  margin:8px 0 0;
  padding:7px 10px;
  color:#1f2329;
  font-size:16px;
  line-height:1.28;
  border-radius:8px;
  background:#fff6dc;
}
.risk-grid{
  display:grid;
  grid-template-columns:1fr;
  gap:8px;
  margin-top:12px;
}
.risk-grid span{
  min-height:38px;
  display:flex;
  align-items:center;
  padding:0 12px;
  color:#1f2329;
  font-size:16px;
  font-weight:700;
  border-radius:8px;
  background:#f3f6ff;
}
.action-list{
  margin:12px 0 0;
  padding-left:22px;
  color:#1f2329;
  font-size:16px;
  line-height:1.45;
  font-weight:600;
}
.action-rail{
  display:grid;
  grid-template-columns:repeat(3,1fr);
  gap:7px;
  margin-top:9px;
}
.action-rail span{
  height:31px;
  display:flex;
  align-items:center;
  justify-content:center;
  color:#fff;
  font-size:16px;
  line-height:1;
  font-weight:700;
  border-radius:8px;
  background:#1456f0;
}
.demo-input{
  height:46px;
  flex:0 0 46px;
  display:flex;
  align-items:center;
  gap:10px;
  padding:8px 12px;
  border-top:1px solid #e5e6eb;
  background:#fff;
}
.demo-input span{
  flex:1;
  height:34px;
  display:flex;
  align-items:center;
  padding:0 12px;
  color:#8f959e;
  font-size:16px;
  line-height:1;
  border-radius:8px;
  background:#f2f3f5;
}
.demo-input b{
  height:34px;
  display:flex;
  align-items:center;
  justify-content:center;
  padding:0 13px;
  color:#fff;
  font-size:16px;
  line-height:1;
  border-radius:8px;
  background:#1456f0;
}
@media (prefers-reduced-motion: no-preference){
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .hero-result,
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .mechanism,
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .evidence{
    animation: sn-rise .6s cubic-bezier(.16,1,.3,1) both;
  }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .mechanism{ animation-delay:.08s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .evidence{ animation-delay:.16s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipeline-beam i{
    animation: sn-flowline 1.2s cubic-bezier(.16,1,.3,1) .38s both;
  }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipe-card{
    animation: sn-chat-in .48s cubic-bezier(.16,1,.3,1) both;
  }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipe-card:nth-of-type(1){ animation-delay:.42s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipe-card:nth-of-type(2){ animation-delay:.52s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipe-card:nth-of-type(3){ animation-delay:.62s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipe-card:nth-of-type(4){ animation-delay:.72s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipe-card:nth-of-type(5){ animation-delay:.82s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipe-arrow{
    animation: sn-pulse-arrow .9s ease-in-out both;
  }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipe-arrow:nth-of-type(1){ animation-delay:.58s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipe-arrow:nth-of-type(2){ animation-delay:.68s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipe-arrow:nth-of-type(3){ animation-delay:.78s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipe-arrow:nth-of-type(4){ animation-delay:.88s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipeline-caption{
    animation: sn-chat-in .48s cubic-bezier(.16,1,.3,1) .95s both;
  }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipeline-outcomes div{
    animation: sn-chat-in .46s cubic-bezier(.16,1,.3,1) both;
  }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipeline-outcomes div:nth-child(1){ animation-delay:1.05s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipeline-outcomes div:nth-child(2){ animation-delay:1.13s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .pipeline-outcomes div:nth-child(3){ animation-delay:1.21s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .question-card{
    animation: sn-chat-in .45s cubic-bezier(.16,1,.3,1) .38s both;
  }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .prompt-row label{
    animation: sn-chat-in .42s cubic-bezier(.16,1,.3,1) both;
  }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .prompt-row label:nth-child(1){ animation-delay:.55s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .prompt-row label:nth-child(2){ animation-delay:.62s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .prompt-row label:nth-child(3){ animation-delay:.69s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .bot-card{
    animation: sn-chat-in .5s cubic-bezier(.16,1,.3,1) .82s both;
  }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .typing-line span{
    animation: sn-typing .9s ease-in-out infinite;
  }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .typing-line span:nth-child(2){ animation-delay:.12s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .typing-line span:nth-child(3){ animation-delay:.24s; }
  .slide-frame.is-current .slide[data-slide-key="shengnong-aily-value-onepage"] .lag-row i{
    animation: sn-bar .9s cubic-bezier(.16,1,.3,1) 1.05s both;
  }
}
@keyframes sn-rise{ from{opacity:0; transform:translateY(14px)} to{opacity:1; transform:none} }
@keyframes sn-chat-in{ from{opacity:0; transform:translateY(10px)} to{opacity:1; transform:none} }
@keyframes sn-typing{ 0%,100%{opacity:.35; transform:translateY(0)} 50%{opacity:1; transform:translateY(-2px)} }
@keyframes sn-bar{ from{width:0} to{width:var(--w)} }
@keyframes sn-flowline{ from{width:0} to{width:100%} }
@keyframes sn-pulse-arrow{ 0%{opacity:.36; transform:rotate(45deg) translate(-4px,-4px)} 55%{opacity:1} 100%{opacity:.86; transform:rotate(45deg) translate(0,0)} }
